// Regenerates packages/core/src/database.types.ts from the LOCAL database schema.
// Run after every migration: pnpm db:types
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { supabaseCli } from './lib/supabase-status.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const types = supabaseCli(['gen', 'types', 'typescript', '--local', '--schema', 'public'], {
  cwd: root,
});
const target = join(root, 'packages/core/src/database.types.ts');
writeFileSync(
  target,
  '// Generated by `pnpm db:types` from supabase/migrations. Do not edit by hand.\n' +
    types.replace(/\r\n/g, '\n'),
);
console.log('Wrote', target);
